// Go⇔TS merge-patch conformance. The corpus at
// public-pkg/parse/testdata/patch_conformance.json is generated by the
// authoritative Go parser together with the registry's schema response for
// its entity; this test holds validatePatch to the same validity and error
// code for every case the client can judge. Regenerate the corpus with:
//
//   go test -tags=unit -run TestEmitPatchConformance -update ./public-pkg/parse/

import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import { SchemaValidationError } from "../core/errors.js";
import type { ResourceSchema } from "../schema.js";
import { validatePatch } from "./validate.js";

interface PatchCase {
  name: string;
  input: Record<string, unknown>;
  valid: boolean;
  errorCode?: string;
  tsApplicable?: boolean;
}

const corpus = JSON.parse(
  readFileSync(new URL("../../../../testdata/patch_conformance.json", import.meta.url), "utf8"),
) as { schema: ResourceSchema; cases: PatchCase[] };

describe("patch conformance corpus", () => {
  it("is non-empty", () => {
    expect(corpus.cases.length).toBeGreaterThan(0);
  });

  const patchSchema = corpus.schema.patch;
  for (const c of corpus.cases) {
    if (c.tsApplicable === false) continue;
    it(c.name, () => {
      expect(patchSchema).toBeDefined();
      if (!patchSchema) return;
      let thrown: unknown;
      try {
        validatePatch(c.input, patchSchema);
      } catch (e) {
        thrown = e;
      }
      if (c.valid) {
        expect(thrown, `${c.name} should validate but threw ${String(thrown)}`).toBeUndefined();
        return;
      }
      expect(thrown, `${c.name} should be rejected`).toBeInstanceOf(SchemaValidationError);
      expect((thrown as SchemaValidationError).code).toBe(c.errorCode);
    });
  }
});
